import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function Signup() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [errorMsg, setErrorMsg] = useState("");
  const navigate = useNavigate();

  const handleSignup = async (e) => {
    e.preventDefault();
    setErrorMsg("");

    if (!username || !password) {
      setErrorMsg("Username și parola sunt obligatorii.");
      return;
    }

    try {
      await axios.post("http://127.0.0.1:5000/signup", {
        username,
        password,
      });
      alert("Cont creat cu succes. Te poți loga acum.");
      navigate("/login");
    } catch (err) {
      console.error("Eroare signup:", err);
      if (err.response && err.response.data && err.response.data.error) {
        setErrorMsg(err.response.data.error);
      } else {
        setErrorMsg("Eroare la crearea contului.");
      }
    }
  };

  return (
    <form onSubmit={handleSignup}>
      <h2>Signup</h2>
      {errorMsg && <p style={{ color: "red" }}>{errorMsg}</p>}
      <input
        placeholder="Username"
        value={username}
        onChange={e => setUsername(e.target.value)}
        required
      />
      <input
        type="password"
        placeholder="Parolă"
        value={password}
        onChange={e => setPassword(e.target.value)}
        required
      />
      <button type="submit">Signup</button>
    </form>
  );
}
